<?php
declare(strict_types=1);require_once __DIR__.'/../config/auth.php';$me=page_require(['ADMIN','VERIFICADOR']);$admin=$me['rol']==='ADMIN';?><!doctype html><html lang="es"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Configuración — Hache Natación</title><style>*{box-sizing:border-box}body{margin:0;background:#f3f6fa;font-family:Manrope,Arial,sans-serif;color:#172033}.wrap{max-width:900px;margin:auto;padding:82px 14px 32px}h1{margin:0 0 6px}.sub{color:#64748b;margin-bottom:18px}.panel{background:#fff;border-radius:15px;padding:15px;margin-bottom:12px}.row{display:grid;grid-template-columns:1fr 100px 120px 90px;gap:8px;align-items:center;padding:9px 0;border-bottom:1px solid #eef2f7}.row input{width:100%;padding:9px;border:1px solid #cbd5e1;border-radius:8px}.btn{border:0;border-radius:9px;padding:9px 12px;font-weight:800;cursor:pointer}.primary{background:#123b5d;color:#fff}.links{display:flex;gap:8px;flex-wrap:wrap}.links a{padding:10px 12px;background:#e8eef2;color:#172033;border-radius:9px;text-decoration:none;font-weight:800}@media(max-width:650px){.row{grid-template-columns:1fr 1fr}.row .name{grid-column:1/-1}}</style></head><body><main class="wrap"><h1>Configuración</h1><div class="sub">Planes y parámetros de Franky</div><div class="panel"><h3>Accesos de configuración</h3><div class="links"><a href="/horarios.php">Horarios</a><?php if($admin):?><a href="/usuarios.php">Usuarios</a><?php endif;?></div></div><div class="panel"><h3>Planes</h3><div id="planes"></div><?php if($admin):?><button id="nuevo" class="btn primary">+ Nuevo plan</button><?php endif;?></div><div class="panel"><h3>Parámetros</h3><div id="cfg"></div></div></main><script>const admin=<?=json_encode($admin)?>,P=document.getElementById('planes'),C=document.getElementById('cfg');async function api(body){const r=await fetch('/api/configuracion.php',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(body)}),d=await r.json();if(!r.ok||!d.ok)throw new Error(d.error||'Error');return d}function planRow(p={id:'',nombre:'',sesiones_semana:3,precio:0,activo:1}){const e=document.createElement('div');e.className='row';e.innerHTML=`<input class="name" value="${String(p.nombre).replace(/"/g,'&quot;')}" ${admin?'':'disabled'}><input type="number" min="1" value="${p.sesiones_semana}" ${admin?'':'disabled'}><input type="number" min="0" step="0.01" value="${p.precio}" ${admin?'':'disabled'}><label><input type="checkbox" ${Number(p.activo)?'checked':''} ${admin?'':'disabled'}> Activo</label>${admin?'<button class="btn primary">Guardar</button>':''}`;if(admin)e.querySelector('button').onclick=async()=>{const i=e.querySelectorAll('input');await api({accion:'PLAN',id:p.id,nombre:i[0].value,sesiones_semana:i[1].value,precio:i[2].value,activo:i[3].checked});load()};return e}async function load(){const r=await fetch('/api/configuracion.php'),d=await r.json();P.innerHTML='';d.planes.forEach(p=>P.appendChild(planRow(p)));C.innerHTML=d.configuracion.map(x=>`<div class="row"><strong class="name">${x.clave}<small style="display:block;color:#64748b">${x.descripcion||''}</small></strong><input style="grid-column:span 2" data-key="${x.clave}" value="${String(x.valor||'').replace(/"/g,'&quot;')}" ${admin?'':'disabled'}>${admin?'<button class="btn primary">Guardar</button>':''}</div>`).join('');if(admin)C.querySelectorAll('button').forEach(b=>b.onclick=async()=>{const i=b.parentElement.querySelector('input');await api({accion:'CONFIG',clave:i.dataset.key,valor:i.value});load()});}<?php if($admin):?>document.getElementById('nuevo').onclick=()=>P.appendChild(planRow());<?php endif;?>load();</script></body></html>